package vn.boardinghub.modules.property;import jakarta.validation.constraints.*;public final class PropertyDtos{private PropertyDtos(){}public record Request(@NotBlank @Size(max=150)String name,@NotBlank @Size(max=255)String address,@Size(max=500)String description){}public record Response(Long id,String name,String address,String description,boolean active){}static Response from(Property p){return new Response(p.getId(),p.getName(),p.getAddress(),p.getDescription(),p.isActive());}}
